/**
 * Office previews (design §7) against REAL services: Postgres (meetless-pg)
 * and LibreOffice (meetless-office), using the committed PPTX / DOCX
 * fixtures generated by python-pptx / python-docx (fixtures/office).
 * Fails loudly when either container is not running: `infra/dev/deps.sh start`.
 */
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type { DerivedPreview, EventPayloads, EventType } from '@meetless/core';
import { BlobFiles, CONVERTER_UNAVAILABLE, DEFAULT_DEV_USERS, OfficeWorker, openPostgres, sha256, SyncService } from '../src/index';
import { IDS, requirePostgres, tempDir, TEST_DATABASE_URL, testSchema, until } from './helpers';

const OFFICE_URL = process.env.MEETLESS_OFFICE_URL ?? 'http://127.0.0.1:55434';
const FIX = resolve(import.meta.dirname, '../../../fixtures/office');
const fixture = (n: string) => new Uint8Array(readFileSync(resolve(FIX, n)));
const DOCX_MEDIA = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const PPTX_MEDIA = 'application/vnd.openxmlformats-officedocument.presentationml.presentation';

let dir: ReturnType<typeof tempDir>;
let schema: ReturnType<typeof testSchema>;
let stores: Awaited<ReturnType<typeof openPostgres>>;
let svc: SyncService;
let worker: OfficeWorker;
let converts = 0;

async function ok<K extends EventType>(actor: string, type: K, payload: EventPayloads[K]) {
  const r = await svc.submit(actor, { id: randomUUID(), type, payload });
  expect(r.status, `${type} by ${actor}`).toBe('accepted');
  return r;
}

/** Uploads the fixture's bytes and appends `artifact.version_added` for it. Returns the blob hash. */
async function publishVersion(artifactId: string, versionId: string, file: string, kind: 'pptx' | 'docx', actor: string = IDS.lin): Promise<string> {
  const bytes = fixture(file);
  const hash = sha256(bytes);
  await svc.putBlob(actor, hash, bytes, kind === 'pptx' ? PPTX_MEDIA : DOCX_MEDIA);
  await ok(actor, 'artifact.version_added', { artifactId, versionId, label: file, date: '2026-11-24', note: file, blobHash: hash, mediaType: kind === 'pptx' ? PPTX_MEDIA : DOCX_MEDIA });
  return hash;
}

function derivedOf(artifactId: string, versionId: string): DerivedPreview | null | undefined {
  return svc.current.artifacts[artifactId]?.versions.find((v) => v.id === versionId)?.derived;
}

async function waitDerived(artifactId: string, versionId: string, ms = 60_000): Promise<DerivedPreview> {
  return until(() => derivedOf(artifactId, versionId), ms, `conversion of ${artifactId}/${versionId}`);
}

beforeAll(async () => {
  await requirePostgres();
  const h = await fetch(`${OFFICE_URL}/health`).catch((e: Error) => {
    throw new Error(`meetless-office not reachable at ${OFFICE_URL} (${e.message}). Run: infra/dev/deps.sh start`);
  });
  expect(h.ok).toBe(true);

  dir = tempDir('office');
  schema = testSchema();
  stores = await openPostgres({ connectionString: TEST_DATABASE_URL, schema: schema.name });
  svc = await SyncService.open({ store: stores.events, blobMeta: stores.blobs, blobFiles: new BlobFiles(dir.path), devUsers: DEFAULT_DEV_USERS, derivations: stores.derivations });
  const counting: typeof fetch = (input, init) => {
    if (String(input).includes('/convert')) converts++;
    return fetch(input, init);
  };
  worker = new OfficeWorker(svc, { url: OFFICE_URL, fetch: counting, retryDelayMs: 50 });
  worker.start();

  await ok(IDS.lin, 'project.created', { projectId: 'P', name: 'CRM 导出' });
  await ok(IDS.lin, 'project.member_added', { projectId: 'P', userId: IDS.ben });
  for (const [artifactId, kind] of [['ppt', 'pptx'], ['doc', 'docx'], ['bad', 'docx']] as const) {
    await ok(IDS.lin, 'artifact.created', { artifactId, projectId: 'P', kind, title: artifactId, where: 'local', needIds: [] });
  }
}, 60_000);

afterAll(async () => {
  await worker?.stop();
  await stores?.events.close();
  await schema?.drop();
  dir?.rm();
});

describe('office preview worker (real LibreOffice conversion)', () => {
  it(
    'PPTX version: one page image and one text per slide',
    async () => {
      await publishVersion('ppt', 'ppt-v1', 'export-deck-v1.pptx', 'pptx');
      const d = await waitDerived('ppt', 'ppt-v1');
      expect(d.status).toBe('partial');
      expect(d.converter).toMatch(/^meetless-office\/1 libreoffice-/);
      expect(d.pageHashes).toHaveLength(4);
      expect(d.texts).toHaveLength(4);
      expect(d.texts[1]).toContain('支持导出全部客户字段');
      expect(d.error).toBeNull();

      // Derived previews are blobs, readable by project members only.
      const png = await svc.blobFiles.readBytes(d.pageHashes[0]!);
      expect([...png.slice(1, 4)].map((c) => String.fromCharCode(c)).join('')).toBe('PNG');
      expect(await svc.canReadBlob(IDS.ben, d.pageHashes[0]!)).toBe(true);
      expect(await svc.canReadBlob(IDS.eve, d.pageHashes[0]!)).toBe(false);
    },
    60_000,
  );

  it(
    'DOCX version: paragraph texts; results are cached by content',
    async () => {
      await publishVersion('doc', 'doc-v1', 'export-design-v1.docx', 'docx');
      const d1 = await waitDerived('doc', 'doc-v1');
      expect(d1.status).toBe('ready');
      expect(d1.texts.length).toBeGreaterThan(0);
      expect(d1.texts.some((t) => t.includes('范围'))).toBe(true);

      const before = converts;
      await publishVersion('doc', 'doc-v1b', 'export-design-v1.docx', 'docx'); // same bytes, new version
      const d2 = await waitDerived('doc', 'doc-v1b');
      expect(converts).toBe(before); // cache hit: no new call to /convert
      expect(d2.texts).toEqual(d1.texts);
      expect(d2.pageHashes).toEqual(d1.pageHashes);
    },
    60_000,
  );

  it(
    'a corrupt file is recorded as failed; the original stays readable',
    async () => {
      const hash = await publishVersion('bad', 'bad-v1', 'corrupt.docx', 'docx');
      const d = await waitDerived('bad', 'bad-v1');
      expect(d).toMatchObject({ status: 'failed', error: 'unreadable', pageHashes: [], texts: [] });
      expect(await svc.blobFiles.exists(hash)).toBe(true);
    },
    60_000,
  );

  it(
    'a converter outage is recorded as failed with converter_unavailable, never as ready',
    async () => {
      await worker.stop();
      // An unused loopback port in the fixed-port test range: never the real container.
      const down = new OfficeWorker(svc, { url: 'http://127.0.0.1:4809', attempts: 2, retryDelayMs: 10 });
      down.start();
      await publishVersion('doc', 'doc-v2', 'export-design-v2.docx', 'docx');
      const failed = await until(() => derivedOf('doc', 'doc-v2'), 20_000, 'outage derived');
      expect(failed).toMatchObject({ status: 'failed', error: CONVERTER_UNAVAILABLE });
      await down.stop();

      // On restart a fresh worker re-queues versions that only failed because the converter was down.
      worker = new OfficeWorker(svc, { url: OFFICE_URL, retryDelayMs: 50 });
      worker.start();
      const recovered = await until(
        () => {
          const d = derivedOf('doc', 'doc-v2');
          return d && d.status !== 'failed' ? d : null;
        },
        60_000,
        'restart recovery',
      );
      expect(recovered.status).not.toBe('failed');
      expect(recovered.texts.length).toBeGreaterThan(0);
    },
    90_000,
  );
});

describe('office preview privacy (controller ruling: scope follows the artifact)', () => {
  it(
    "a private artifact's derived event reaches only its owner, never another project member",
    async () => {
      await ok(IDS.lin, 'artifact.created', { artifactId: 'priv', projectId: 'P', kind: 'pptx', title: 'private deck', where: 'local', needIds: [], private: true });
      await publishVersion('priv', 'priv-v1', 'export-deck-v1.pptx', 'pptx');
      await waitDerived('priv', 'priv-v1');

      const forOwner = svc.eventsFor(IDS.lin, 0).events.find((e) => e.type === 'artifactVersion.derived' && e.payload.versionId === 'priv-v1');
      const forMember = svc.eventsFor(IDS.ben, 0).events.find((e) => e.type === 'artifactVersion.derived' && e.payload.versionId === 'priv-v1');
      expect(forOwner).toBeDefined();
      expect(forMember).toBeUndefined();
    },
    60_000,
  );
});
